def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Simple approach: find first differing character
    min_len = min(len(s_in), len(s_out))

    # Look for first difference
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found a difference at position i
            old_char = s_in[i]
            new_char = s_out[i]
            return (old_char, new_char, i)

    # If we reach here, one string is prefix of the other
    if len(s_in) < len(s_out):
        # Insertion
        return (s_in[-1], s_out[len(s_in)], len(s_in) - 1) if len(s_in) > 0 else (None, s_out[0], 0)
    elif len(s_in) > len(s_out):
        # Deletion
        return (s_in[len(s_out)], '', len(s_out))

    return (None, None, -1)

